select case when rating >= 4.2 then 'high' when rating >= 1.5 then 'mid' else 'low' end as rating_bucket, sum(rating) as total_rating, sum(sum(rating)) over (order by case when rating >= 4.2 then 'high' when rating >= 1.5 then 'mid' else 'low' end) as cumulative_rating from suppliers where rating <= 4.2 group by case when rating >= 4.2 then 'high' when rating >= 1.5 then 'mid' else 'low' end order by rating_bucket, total_rating desc;
